package edu.pe.cibertec.saibm.inventario.domain.model; import java.time.Instant; import java.util.UUID; public final class Hold {private final UUID id;private final String operationKey,bookId,requestHash;private final int quantity;private final Instant expiresAt;private InventoryState state; public Hold(UUID i,String k,String b,int q,Instant e,String h,InventoryState s){id=i;operationKey=k;bookId=b;quantity=q;expiresAt=e;requestHash=h;state=s;} public static Hold held(UUID i,String k,String b,int q,Instant e,String h){return new Hold(i,k,b,q,e,h,InventoryState.HELD);} public UUID id(){return id;}public String operationKey(){return operationKey;}public String bookId(){return bookId;}public int quantity(){return quantity;}public Instant expiresAt(){return expiresAt;}public String requestHash(){return requestHash;}public InventoryState state(){return state;}public void transition(InventoryState s){state=s;}public void reject(){state=InventoryState.REJECTED;}}
